def icon_with_text(icon_name, text, size=20, color="#9CA3AF"):
    """Retourne une icône + texte alignés"""
    return f'''
    <div style="display: flex; align-items: center; gap: 0.75rem; color: {color};">
        {icon(icon_name, size, color)}
        <span>{text}</span>
    </div>
    '''